-- Run once in SQL Developer as your intended schema (e.g. DELTAMAX_V5).
CREATE TABLE MIGR_RUNS (RUN_ID VARCHAR2(32) PRIMARY KEY, STATUS VARCHAR2(20) NOT NULL, STARTED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, FINISHED_AT TIMESTAMP, DETAILS VARCHAR2(2000));
CREATE TABLE MIGR_CONTROL (CONTROL_KEY VARCHAR2(20) PRIMARY KEY, RUN_ID VARCHAR2(32) NOT NULL REFERENCES MIGR_RUNS(RUN_ID));
CREATE TABLE MIGR_FILES (RUN_ID VARCHAR2(32) NOT NULL REFERENCES MIGR_RUNS(RUN_ID), FILE_KEY VARCHAR2(250) NOT NULL, COLUMNS_JSON CLOB NOT NULL, ROW_COUNT NUMBER NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_MIGR_FILES PRIMARY KEY(RUN_ID,FILE_KEY));
CREATE TABLE MIGR_ROWS (RUN_ID VARCHAR2(32) NOT NULL, FILE_KEY VARCHAR2(250) NOT NULL, ROW_NUM NUMBER NOT NULL, PAYLOAD CLOB NOT NULL, CONSTRAINT PK_MIGR_ROWS PRIMARY KEY(RUN_ID,FILE_KEY,ROW_NUM), CONSTRAINT FK_MIGR_ROWS_FILE FOREIGN KEY(RUN_ID,FILE_KEY) REFERENCES MIGR_FILES(RUN_ID,FILE_KEY));
CREATE INDEX IX_MIGR_ROWS_STAGE ON MIGR_ROWS(RUN_ID,FILE_KEY);
CREATE TABLE MIGR_LOG (LOG_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, RUN_ID VARCHAR2(32) NOT NULL REFERENCES MIGR_RUNS(RUN_ID), STEP_NAME VARCHAR2(100) NOT NULL, STATUS VARCHAR2(20) NOT NULL, RECORD_COUNT NUMBER, DETAILS VARCHAR2(2000), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE MIGR_JSON_LOGS (RUN_ID VARCHAR2(32) NOT NULL REFERENCES MIGR_RUNS(RUN_ID), LOG_NAME VARCHAR2(250) NOT NULL, PAYLOAD CLOB NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_MIGR_JSON_LOGS PRIMARY KEY(RUN_ID,LOG_NAME));
